    o += `<circle cx="${f(x - 2.6 * s)}" cy="${f(y - 26.5 * s)}" r="${f(1.2 * s)}" fill="white"/><circle cx="${f(x + 2.6 * s)}" cy="${f(y - 26.5 * s)}" r="${f(1.2 * s)}" fill="white"/>`;
