    V.forEach(([, v], i) => { body += `<g class="b3"><rect class="growy growy3" style="transition-delay:${f(0.2 + i * 0.25)}s" x="${bx(i) - 13}" y="${f(BASE - v * SC)}" width="26" height="${f(v * SC)}" rx="2" fill="${C.orange}"/></g>`; });
    body += at(3, 'pop', text(bx(0), f(BASE - V[0][1] * SC - 10), '28.5', { size: 18, color: C.orange }), 0.6);
    body += at(3, 'pop', text(bx(5), f(BASE - V[5][1] * SC - 10), '59.4', { size: 18, color: C.orange }), 1.7);
    body += at(3, 'fin', text(bx(0), 326, '2009', { size: 18, weight: 600 }) + text(bx(5), 326, '2024', { size: 18, weight: 600 }), 0.3);
