  const landSvg = (sw = 1.2) => `<path d="${LAND}" fill="none" stroke="${C.green}" stroke-width="${sw * 2}" stroke-linejoin="round"/><path d="${LAND}" fill="${C.mint}" stroke="${C.mint}" stroke-width="${f(sw * 0.8)}" stroke-linejoin="round"/>`;

