    body += at(3, 'pop', tag(96, 230, '판문점', HOT, { size: 20 }) + `<path d="M120 214 L150 194" stroke="${C.orange}" stroke-width="3" stroke-linecap="round"/>`, 0.6);
    body += ring(PX, PY - 26, 18, 3, C.orange, 0.8);
    // 4칸: 이름
