    body += tree(236, 136, 13) + tree(36, 142, 11);
    // 도시: 칸마다 건물이 자란다
    body += `<path d="M392 192 H620" stroke="${C.ink}" stroke-width="3" stroke-linecap="round"/>`;
    const BLD = [[420, 30, 50, 1], [470, 28, 40, 1], [560, 30, 56, 1], [446, 26, 86, 2], [604, 26, 74, 2], [515, 34, 126, 3], [588, 22, 104, 3]];
    BLD.forEach(([x, w, h, n], i) => { body += `<g class="b${n}"><g class="growy growy${n}" style="transition-delay:${f(0.3 + (i % 3) * 0.3)}s">${building(x, 192, w, h)}</g></g>`; });
    // 열 사람: 칸마다 자리
    const V = [[60, 278], [105, 278], [150, 278], [195, 278], [60, 330], [105, 330], [150, 330], [195, 330]];
    const U = [[432, 278], [477, 278], [522, 278], [567, 278], [432, 330], [477, 330], [522, 330], [567, 330]];
    const COL = [C.green, C.orange, C.blue, C.purple];
    for (let i = 0; i < 10; i++) {
      const city = (n) => (n === 1 ? i < 3 : n === 2 ? i < 6 : i < 8);
      const pos = [1, 2, 3].map((n) => (city(n) ? U[i] : V[i - 3]));
      body += at(1, 'fin', `<g class="mv" style="${mvStyle(pos)};transition-delay:${f((i % 3) * 0.25)}s">${person(0, 0, COL[i % 4], 1.25, { bun: i % 2 === 1 })}</g>`, f(0.1 * i));
    }
